import React from 'react';

export default function EventSalesInputForm({ values, onChange, defaultConfig, recommendedDiscount }) {
  const { devices } = defaultConfig;
  const selected = devices.find(d => d.id === values.deviceModel);

  return (
    <div className="mb-4 space-y-4">
      {/* 추가 혜택 */}
      <div>
        <label className="block text-sm font-medium mb-1">추가 혜택</label>
        <div className="w-full border p-2 rounded-md bg-gray-50 text-sm whitespace-pre-wrap">
          {values.others || '선택된 요금제의 혜택 정보가 없습니다.'}
        </div>
      </div>

      {/* 단말기 모델 */}
      <div>
        <label className="block text-sm font-medium mb-1">단말기 모델</label>
        <select
          name="deviceModel"
          value={values.deviceModel}
          onChange={e => onChange('deviceModel', e.target.value)}
          className="w-full border p-2 rounded"
        >
          <option value="">모델을 선택하세요</option>
          {devices.map(d => (
            <option key={d.id} value={d.id}>{d.name}</option>
          ))}
        </select>
      </div>

      {/* 메모리 옵션 및 출고가 표시 */}
      {selected && (
        <div>
          <label className="block text-sm font-medium mb-1">메모리 옵션</label>
          <select
            name="deviceVariant"
            value={values.deviceVariant}
            onChange={e => onChange('deviceVariant', e.target.value)}
            className="w-full border p-2 rounded"
          >
            <option value="">용량을 선택하세요</option>
            {selected.variants.map(v => (
              <option key={v.id} value={v.id}>{v.memory}</option>
            ))}
          </select>
          {values.deviceVariant && (
            <p className="mt-2 text-sm font-medium">
              출고가: {selected.variants.find(v => v.id === values.deviceVariant).price.toLocaleString()}원
            </p>
          )}
        </div>
      )}

      {/* 할인 선택 */}
      <div>
        <label className="block text-sm font-medium mb-1">할인 선택</label>
        <select
          name="discountType"
          value={values.discountType}
          onChange={e => onChange('discountType', e.target.value)}
          className="w-full border p-2 rounded"
        >
          <option value="">할인 없음</option>
          <option value="contract">요금할인 (25%)</option>
          <option value="subsidy">공시 지원금</option>
        </select>
        {recommendedDiscount && (
          <p className="mt-1 text-sm text-blue-600">추천 할인: {recommendedDiscount}</p>
        )}

        {values.discountType === 'subsidy' && (
          <div className="mt-2">
            <label className="block text-sm font-medium mb-1">공시 지원금 금액</label>
            <input
              type="number"
              name="subsidyAmount"
              value={values.subsidyAmount}
              onChange={e => onChange('subsidyAmount', e.target.value)}
              placeholder="지원금 금액을 입력하세요"
              className="w-full border p-2 rounded"
            />
          </div>
        )}
      </div>

      {/* 부분 수납 */}
      <div>
        <label className="block text-sm font-medium mb-1">부분 수납</label>
        <input
          type="number"
          name="partialPayment"
          value={values.partialPayment}
          onChange={e => onChange('partialPayment', e.target.value)}
          placeholder="부분 수납"
          className="w-full border p-2 rounded"
        />
      </div>

      {/* 5G 시니어일 때만 기초연금 선택 */}
      {values.category === '5G 시니어 (만 65세 이상)' && (
        <div>
          <label className="block text-sm font-medium mb-1">기초연금 수급 여부</label>
          <select
            name="pensionApply"
            value={values.pensionApply || ''}
            onChange={e => onChange('pensionApply', e.target.value)}
            className="w-full border p-2 rounded"
          >
            <option value="">— 선택하세요 —</option>
            <option value="yes">기초연금 수급 적용</option>
            <option value="no">기초연금 수급 미적용</option>
          </select>
        </div>
      )}

      {/* 할부개월 */}
      <div>
        <label className="block text-sm font-medium mb-1">할부개월</label>
        <select
          name="installments"
          value={values.installments}
          onChange={e => onChange('installments', e.target.value)}
          className="w-full border p-2 rounded"
        >
          {[6, 12, 24, 36].map(n => (
            <option key={n} value={n}>{n}개월</option>
          ))}
        </select>
      </div>
    </div>
  );
}