import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import EventSalesFilterForm from './EventSalesFilterForm';
import EventSalesInputForm  from './EventSalesInputForm';
import EventSalesResult     from './EventSalesResult';
import { phonePlans }       from '../config/phonePlanConfig';
import { defaultEventConfig } from '../config/eventConfig';

export default function EventSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    others: '',
    deviceModel: '',
    deviceVariant: '',
    discountType: '',
    partialPayment: 0,
    subsidyAmount: 0,
    installments: 24,
    pensionApply: '', // 기초연금 수급 여부
  });
  const [result, setResult] = useState(null);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');
  const monthlyRate = 0.059 / 12;

  // 필터/입력 변경
  const handleFilterChange = (field, value) => {
    setValues(prev => ({
      ...prev,
      [field]: value,
      ...(field === 'planId' && {
        planCost: phonePlans.find(p => p.id === value)?.monthlyFee || 0,
        others:   phonePlans.find(p => p.id === value)?.others    || '',
      }),
      ...(field === 'category' && { planId: '', planCost: 0, others: '' }),
      ...(field === 'dataFilter' && { category: '', planId: '', planCost: 0, others: '' }),
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  const handleInputChange = (name, value) => {
    setValues(prev => ({
      ...prev,
      [name]: ['partialPayment','subsidyAmount','installments'].includes(name)
        ? Number(value)
        : value,
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  // 시니어 여부 & 기초연금 선택
  const isSenior = values.category === '5G 시니어 (만 65세 이상)';
  const hasPension = values.pensionApply === 'yes';

  // 계산 가능 여부
  const canCalc =
    values.planCost > 0 &&
    values.deviceModel !== '' &&
    values.deviceVariant !== '' &&
    values.discountType !== '' &&
    (!isSenior || values.pensionApply !== '');

  // 계산 로직
  const handleCalculate = () => {
    if (!canCalc) return;
    const {
      planCost,
      deviceModel,
      deviceVariant,
      discountType,
      partialPayment,
      subsidyAmount,
      installments,
    } = values;

    // 단말 기본 출고가 조회
    const basePrice = defaultEventConfig.devices
      .find(d => d.id === deviceModel)?.variants
      .find(v => v.id === deviceVariant)?.price || 0;

    // 선납금/지원금 차감
    const principalPartial = basePrice - partialPayment;
    const principalSubsidy  = principalPartial - subsidyAmount;

    // 기초연금 할인액
    let appliedPensionDiscount = 0;
    if (isSenior && hasPension) {
      appliedPensionDiscount = Math.min(planCost * 0.5, 12100);
    }

    // 요금제 월 비용: 기초연금 적용시에도 그대로 원가
    const monthlyPlanCost = planCost;

    // 단말 할부 계산 (이자율 기반)
    const deviceInstallmentContract = installments > 0
      ? Math.ceil(
          (principalPartial * monthlyRate) /
          (1 - Math.pow(1 + monthlyRate, -installments))
        ) : 0;
    const deviceInstallmentSubsidy = installments > 0
      ? Math.ceil(
          (principalSubsidy * monthlyRate) /
          (1 - Math.pow(1 + monthlyRate, -installments))
        ) : 0;

    // 선택 시 단말 할부
    const deviceInstallment =
      discountType === 'subsidy'
        ? deviceInstallmentSubsidy
        : deviceInstallmentContract;

    // 기본 총납부
    const baseTotal = monthlyPlanCost + deviceInstallment;
    // 기초연금 할인 시 차감
    const totalPayment = isSenior && hasPension
      ? baseTotal - appliedPensionDiscount
      : baseTotal;

    // 절감액(추천 할인) 계산: 공시 vs 요금할인 시 비교
    // 공시 시나리오 총 = planCost + deviceInstallmentSubsidy
    const totalSubsidyScenario = planCost + deviceInstallmentSubsidy;
    // 요금할인 시나리오 총 = planCost*0.75 + deviceInstallmentContract
    const totalContractScenario = planCost * 0.75 + deviceInstallmentContract;
    const savings =
      discountType === 'contract'
        ? totalSubsidyScenario - totalContractScenario
        : totalContractScenario - totalSubsidyScenario;
    const recommended =
      totalContractScenario < totalSubsidyScenario
        ? '요금할인'
        : '공시 지원금';

    setResult({ monthlyPlanCost, deviceInstallment, totalPayment, savings, appliedPensionDiscount });
    setRecommendedDiscount(recommended);
  };

  return (
    <div className="flex justify-center bg-gray-100 p-4 min-h-screen items-start pt-8">
      <div className="w-full max-w-lg bg-white rounded-lg shadow-lg p-6">
        <h1 className="text-2xl font-bold mb-2 text-center">KT 이벤트 계산기</h1>
        <p className="text-center text-red-600 text-sm mb-4">
          주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.
        </p>

        <EventSalesFilterForm values={values} onChange={handleFilterChange} phonePlans={phonePlans} />
        <EventSalesInputForm values={values} onChange={handleInputChange} defaultConfig={defaultEventConfig} recommendedDiscount={recommendedDiscount} />

        {/* 시니어 카테고리 시 기초연금 선택 */}
        {isSenior && (
          <div className="mb-4">
            <label className="block text-sm font-medium mb-1">기초연금 수급 여부</label>
            <select
              name="pensionApply"
              value={values.pensionApply}
              onChange={e => handleInputChange('pensionApply', e.target.value)}
              className="w-full border p-2 rounded-md"
            >
              <option value="">선택하세요</option>
              <option value="yes">기초연금 수급 적용</option>
              <option value="no">기초연금 수급 미적용</option>
            </select>
          </div>
        )}

        <button
          type="button"
          onClick={handleCalculate}
          disabled={!canCalc}
          className={`w-full py-2 rounded-lg mb-3 transition ${
            canCalc
              ? 'bg-blue-600 text-white hover:bg-blue-700'
              : 'bg-gray-300 text-gray-500 cursor-not-allowed'
          }`}
        >
          계산하기
        </button>

        {result && (
          <EventSalesResult
            monthlyPlanCost={result.monthlyPlanCost}
            deviceInstallment={result.deviceInstallment}
            totalPayment={result.totalPayment}
            savings={result.savings}
            appliedPensionDiscount={result.appliedPensionDiscount}
            discountType={values.discountType}
            pensionApply={values.pensionApply}
          />
        )}

        <button
          type="button"
          onClick={() => navigate('/')}
          className="w-full bg-gray-200 text-gray-700 py-2 rounded-lg mt-2"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
