import React from 'react';

export default function EventSalesFilterForm({ values, onChange, phonePlans }) {
  // 카테고리 기준
  const categoryOptions = ['전체', ...new Set(phonePlans.map(p => p.category))];

  // 선택된 카테고리에 따른 요금제 옵션
  const planOptions = [
    { value: '', label: '전체' },
    ...phonePlans
      .filter(p => !values.category || values.category === '' || p.category === values.category)
      .map(p => ({ value: p.id, label: `${p.name} (${p.monthlyFee.toLocaleString()}원)` }))
  ];

  // 선택된 요금제에 따른 데이터 옵션 (planId 우선)
  const selectedPlan = phonePlans.find(p => p.id === values.planId);
  const dataOptions = selectedPlan
    ? [{ value: selectedPlan.data, label: selectedPlan.data }]
    : [
        { value: '', label: '전체' },
        ...Array.from(
          new Set(
            phonePlans
              .filter(p => !values.category || values.category === '' || p.category === values.category)
              .map(p => p.data)
          )
        ).map(data => ({ value: data, label: data }))
      ];

  return (
    <div className="mb-4 space-y-4">
      {/* 카테고리 선택 */}
      <Select
        label="카테고리"
        name="category"
        options={categoryOptions.map(opt => ({ value: opt === '전체' ? '' : opt, label: opt }))}
        value={values.category}
        onChange={onChange}
      />
      {/* 요금제 선택 */}
      <Select
        label="요금제"
        name="planId"
        options={planOptions}
        value={values.planId}
        onChange={onChange}
      />
      {/* 데이터 선택 */}
      <Select
        label="데이터"
        name="dataFilter"
        options={dataOptions}
        value={values.dataFilter}
        onChange={onChange}
      />
    </div>
  );
}

function Select({ label, name, options, value, onChange }) {
  return (
    <div>
      <label className="block text-sm font-medium mb-1">{label}</label>
      <select
        name={name}
        value={value}
        onChange={e => onChange(name, e.target.value)}
        className="w-full border p-2 rounded"
      >
        {options.map(opt => (
          <option key={opt.value} value={opt.value}>{opt.label}</option>
        ))}
      </select>
    </div>
  );
}
